<div class="lr-widget">
  <canvas id="stage" width="680" height="360"></canvas>
  <div class="lr-controls">
    <label for="eta-slider">学习率 η</label>
    <input type="range" id="eta-slider" min="0.01" max="1.0" step="0.01" value="0.1">
    <span class="lr-val mono" id="etaDisplay">0.10</span>
    <button class="lr-btn" id="reset">重置</button>
    <button class="lr-btn accent" id="pause">暂停</button>
  </div>
  <div class="lr-readout">
    <span>步数 <span class="mono" id="stepDisplay">0</span></span>
    <span>当前位置 <span class="mono" id="posDisplay">(1.50, 2.25)</span></span>
    <span style="margin-left:auto;font-size:11px;color:var(--text2);">损失函数 y = x²</span>
  </div>
