<script>
  (function() {
    const root = document.documentElement;
    const tok = n => getComputedStyle(root).getPropertyValue(n).trim();
    const canvas = document.getElementById('stage');
    const ctx = canvas.getContext('2d');

    // state (契约 state_model)
    let eta = 0.1;
    let x = 1.5;
    let stepCount = 0;
    let isRunning = true;
    let trail = [[1.5, 2.25]];

    // DOM refs
    const etaSlider = document.getElementById('eta-slider');
    const etaDisplay = document.getElementById('etaDisplay');
    const stepDisplay = document.getElementById('stepDisplay');
    const posDisplay = document.getElementById('posDisplay');
    const resetBtn = document.getElementById('reset');
    const pauseBtn = document.getElementById('pause');

    // 辅助: 读取主题色 (每帧重读以跟随主题切换)
    function getColors() {
      return {
        ink: tok('--ink'),
        accent: tok('--accent'),
        line: tok('--line'),
        text2: tok('--text2'),
        bg: tok('--bg'),
        card: tok('--card'),
        bg2: tok('--bg2'),
        mono: tok('--mono'),
      };
    }

    // 绘制损失曲线 + trail + 当前点
    function draw() {
      const W = canvas.width, H = canvas.height;
      const C = getColors();
      const dark = root.getAttribute('data-theme') === 'lab' || root.getAttribute('data-theme') === 'cobalt-grid';

      // 映射: x ∈ [-2.2, 2.2] → px, y ∈ [0, 4.5] → px (y向下)
      const pad = 40;
      const plotW = W - 2 * pad;
      const plotH = H - 2 * pad;
      const xMin = -2.2, xMax = 2.2, yMin = -0.2, yMax = 4.5;

      function toPixel(xv, yv) {
        const px = pad + (xv - xMin) / (xMax - xMin) * plotW;
        const py = pad + (yMax - yv) / (yMax - yMin) * plotH;
        return [px, py];
      }

      ctx.clearRect(0, 0, W, H);

      // 背景网格 (hairline tick scale — signature)
      ctx.strokeStyle = C.line;
      ctx.lineWidth = 0.5;
      ctx.setLineDash([3, 4]);
      for (let xv = -2; xv <= 2; xv += 0.5) {
        const [px] = toPixel(xv, 0);
        ctx.beginPath();
        ctx.moveTo(px, pad);
        ctx.lineTo(px, H - pad);
        ctx.stroke();
      }
      for (let yv = 0; yv <= 4; yv += 0.5) {
        const [, py] = toPixel(0, yv);
        ctx.beginPath();
        ctx.moveTo(pad, py);
        ctx.lineTo(W - pad, py);
        ctx.stroke();
      }
      ctx.setLineDash([]);

      // 坐标轴
      ctx.strokeStyle = C.text2;
      ctx.lineWidth = 1;
      const [x0, y0] = toPixel(0, 0);
      ctx.beginPath();
      ctx.moveTo(pad, y0);
      ctx.lineTo(W - pad, y0);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x0, pad);
      ctx.lineTo(x0, H - pad);
      ctx.stroke();

      // 刻度标签 (mono)
      ctx.fillStyle = C.text2;
      ctx.font = `10px ${C.mono}`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      for (let xv = -2; xv <= 2; xv += 1) {
        const [px] = toPixel(xv, 0);
        ctx.fillText(xv.toFixed(1), px, y0 + 4);
      }
      ctx.textAlign = 'right';
      ctx.textBaseline = 'middle';
      for (let yv = 0; yv <= 4; yv += 1) {
        const [, py] = toPixel(0, yv);
        ctx.fillText(yv.toFixed(1), x0 - 6, py);
      }

      // 损失曲线 y = x^2 (精细采样)
      ctx.strokeStyle = C.ink;
      ctx.lineWidth = 1.5;
      ctx.globalAlpha = 0.6;
      ctx.beginPath();
      for (let px = pad; px <= W - pad; px += 1) {
        const xv = xMin + (px - pad) / plotW * (xMax - xMin);
        const yv = xv * xv;
        const [, py] = toPixel(xv, yv);
        if (px === pad) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      }
      ctx.stroke();
      ctx.globalAlpha = 1;

      // 绘制 trail (路径连线 + 点)
      if (trail.length > 0) {
        // 连线
        ctx.strokeStyle = C.accent;
        ctx.lineWidth = 2;
        ctx.globalAlpha = 0.7;
        ctx.beginPath();
        for (let i = 0; i < trail.length; i++) {
          const [xv, yv] = trail[i];
          const [px, py] = toPixel(xv, yv);
          if (i === 0) ctx.moveTo(px, py);
          else ctx.lineTo(px, py);
        }
        ctx.stroke();
        ctx.globalAlpha = 1;

        // 历史点 (小圆)
        for (let i = 0; i < trail.length - 1; i++) {
          const [xv, yv] = trail[i];
          const [px, py] = toPixel(xv, yv);
          ctx.fillStyle = C.accent;
          ctx.globalAlpha = 0.3;
          ctx.beginPath();
          ctx.arc(px, py, 3, 0, Math.PI * 2);
          ctx.fill();
        }
        ctx.globalAlpha = 1;

        // 当前点 (高亮, 带微光 — lab signature)
        const [cx, cy] = trail[trail.length - 1];
        const [px, py] = toPixel(cx, cy);
        if (dark) {
          ctx.shadowColor = C.accent;
          ctx.shadowBlur = 14;
        }
        ctx.fillStyle = C.accent;
        ctx.beginPath();
        ctx.arc(px, py, 7, 0, Math.PI * 2);
        ctx.fill();
        ctx.shadowBlur = 0;

        // 当前点外圈
        ctx.strokeStyle = C.card;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(px, py, 7, 0, Math.PI * 2);
        ctx.stroke();
      }

      // 角落 mono 读数 (stepCount, eta) — signature
      ctx.fillStyle = C.text2;
      ctx.font = `11px ${C.mono}`;
      ctx.textAlign = 'left';
      ctx.textBaseline = 'top';
      ctx.fillText(`η = ${eta.toFixed(2)}`, pad + 8, pad + 6);
      ctx.fillText(`步数 ${stepCount}`, pad + 8, pad + 20);
    }

    // 单一 update() 入口: 从当前 state 重绘 canvas + 更新 DOM 读数
    function update() {
      // 更新 DOM 读数
      etaDisplay.textContent = eta.toFixed(2);
      stepDisplay.textContent = stepCount;
      const last = trail[trail.length - 1];
      if (last) {
        posDisplay.textContent = `(${last[0].toFixed(2)}, ${last[1].toFixed(2)})`;
      }
      // 重绘 canvas
      draw();
    }

    // 动画步进 (每次 update 若 isRunning 且 stepCount<100)
    function step() {
      if (isRunning && stepCount < 100) {
        const g = 2 * x;          // 梯度
        x = x - eta * g;          // 梯度下降更新
        stepCount++;
        trail.push([x, x * x]);
        update();
      }
    }

    // 重置状态 (契约: 重置 x=1.5, stepCount=0, trail=[[1.5,2.25]], isRunning=true)
    function resetState() {
      eta = parseFloat(etaSlider.value);
      x = 1.5;
      stepCount = 0;
      isRunning = true;
      trail = [[1.5, 2.25]];
      pauseBtn.textContent = '暂停';
      update();
    }

    // 切换运行/暂停
    function togglePause() {
      isRunning = !isRunning;
      pauseBtn.textContent = isRunning ? '暂停' : '继续';
      // 如果从暂停恢复且步数未满，立即走一步
      if (isRunning && stepCount < 100) {
        // 下一帧动画会处理
      }
    }

    // 事件绑定 (契约 interactions)
    etaSlider.addEventListener('input', function(e) {
      eta = parseFloat(e.target.value);
      // 重置 (契约: 重置 x=1.5, stepCount=0, trail=[[1.5,2.25]], isRunning=true)
      x = 1.5;
      stepCount = 0;
      isRunning = true;
      trail = [[1.5, 2.25]];
      pauseBtn.textContent = '暂停';
      update();
    });

    resetBtn.addEventListener('click', resetState);

    pauseBtn.addEventListener('click', togglePause);

    // 动画循环: 每帧尝试步进 (若 isRunning 且未满)
    let lastTime = 0;
    const STEP_INTERVAL = 60; // ms, 约 16 fps 但每步间隔可控
    function animate(time) {
      if (!lastTime) lastTime = time;
      if (time - lastTime >= STEP_INTERVAL) {
        lastTime = time;
        step();
      }
      requestAnimationFrame(animate);
    }

    // 初始绘制 (契约 initial_paint)
    // 状态已设好: eta=0.1, x=1.5, stepCount=0, trail=[[1.5,2.25]], isRunning=true
    // 但首帧即 mid-action: 已经走了一步? 契约说 "已走 0 步但即将走第一步"
    // 我们让动画立即开始, 但首帧显示 stepCount=0, 起点高亮
    // 为了 "活" 的感觉, 我们让动画在 60ms 后走第一步
    update();

    // 启动动画循环
    requestAnimationFrame(animate);

    // 主题变化时重绘 (MutationObserver)
    const observer = new MutationObserver(() => {
      update();
    });
    observer.observe(root, { attributes: true, attributeFilter: ['data-theme'] });

    // 窗口 resize 不改变 canvas 逻辑尺寸, 但 style 自适应
    // 无需额外处理
  })();
</script>
